from typing import Any, Dict, List, Optional, Tuple
from dataclasses import dataclass


@dataclass
class ValidationError:
    """配置验证错误"""
    field: str
    message: str
    code: str
    value: Any = None


class ConfigValidator:
    """统一配置验证框架"""

    @staticmethod
    def validate_required(value: Any, field_name: str) -> Optional[ValidationError]:
        """验证必填字段"""
        if value is None or (isinstance(value, str) and not value.strip()):
            return ValidationError(
                field=field_name,
                message=f"Required field '{field_name}' is missing or empty",
                code="REQUIRED_FIELD_MISSING",
                value=value
            )
        return None

    @staticmethod
    def validate_type(value: Any, expected_type: type, field_name: str) -> Optional[ValidationError]:
        """验证类型"""
        if not isinstance(value, expected_type):
            return ValidationError(
                field=field_name,
                message=f"Field '{field_name}' expected type {expected_type.__name__}, got {type(value).__name__}",
                code="INVALID_TYPE",
                value=value
            )
        return None

    @staticmethod
    def validate_range(value: Any, min_val: Any, max_val: Any, field_name: str) -> Optional[ValidationError]:
        """验证数值范围"""
        if isinstance(value, (int, float)):
            if value < min_val or value > max_val:
                return ValidationError(
                    field=field_name,
                    message=f"Field '{field_name}' value {value} out of range [{min_val}, {max_val}]",
                    code="VALUE_OUT_OF_RANGE",
                    value=value
                )
        return None

    @staticmethod
    def validate_in_choices(value: Any, choices: List[Any], field_name: str) -> Optional[ValidationError]:
        """验证枚举值"""
        if value not in choice:
            return ValidationError(
                field=field_name,
                message=f"Field '{field_name}' value '{value}' not in allowed choices: {choice}",
                code="INVALID_CHOICE",
                value=value
            )
        return None


